from taf.collectors.syscomdump.factory import SyscomdumpCollectorFactory
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class syscomdump(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _factory = SyscomdumpCollectorFactory()

    def create_syscomdump_collector(self,
                                    name,
                                    executor,
                                    options=None,
                                    syscomdump_path=None,
                                    target_file_name=None,
                                    stop_timeout=None,
                                    container=None,
                                    sudo_password=None):
        """
        Create Syscomdump Collector from given configuration

        :param str name: name of collector
        :param dict executor: setup info host, user, password,in dict format
        :param str options: (optional) syscomdump options (except for "-w"), default: empty string
        :param str syscomdump_path: (optional) path of syscomdump executable, default value: "syscomdump"
        :param str target_file_name: (optional) file name part of the path under which the pcap file is
                                    stored locally during collect_collectors, default: "[collector_name].pcap"
        :param str sudo_password: (optional) password for sudo
        :param float stop_timeout: (optional)  stop timeout is the time to wait after sending CTRL-C for the process
                                    to terminate, as a float.
        :param str container: (optional) container name substring if syscomdump need to be run under container using
                             lxc-attach

        :return: SyscomdumpCollector : created object of SyscomdumpCollector
        """

        configuration = {'name': name,
                         'executor': executor}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["syscomdump_path", "target_file_name", "sudo_password", "options",
                                  "container", "stop_timeout"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        logger.info("Creating Syscomdump Collector with alias name :" + name)
        syscomdump = self._factory.create(configuration=configuration, existing_arguments={})
        logger.info("Syscomdump Collector created successfully")
        self.set_alias(name, syscomdump)
